head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf31207";
scwin.i = null;
scwin.pathname = undefined;
scwin.qry = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    (document.category || { elements: [] }).action = "/CalculateRelatedDisclosure.do?method=getSameCategory";
    $c.util.getComponent("dma_makeExcelDataReq").set("isurCd", $c.util.getComponent('ipt_ISU_CD').getValue());
    const jsonText = await scwin.tx_init_xhr();
    scwin.makeCategory(jsonText);
    const ISU_CD = $c.util.getCookie("ISU_CD");
    const COM_NM = $c.util.getCookie("COM_NM");
    $c.util.getComponent("dma_makeExcelDataReq").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_makeExcelDataReq").set("COM_NM", COM_NM);
    $c.util.getComponent("dma_makeExcelDataReq").set("nowDate", $c.date.formatDate("yyyymmdd"));
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_frmISU_CD = { action: "", method: 'post', target: '' };

try { scwin.pathname =location.pathname; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31207' }); }

try { scwin.qry =location.search; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31207' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf31207.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_70_onclick
 * @description img_70 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_70_onclick = function(e){
    try {
        IsurcdSearch2('ISU_CD','COM_NM',315,155)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31207.img_70_onclick' }); }
};

/**
 * @method
 * @name img_70_onmouseover
 * @description img_70 onmouseover 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_70_onmouseover = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.style.cursor='hand';

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31207.img_70_onmouseover' }); }
};scwin.btn_Calc_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.calc()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf31207.btn_Calc_onclick' }); }
};

/**
 * @method
 * @name btn_ExcelDown_onclick
 * @description btn_ExcelDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ExcelDown_onclick = async function(e){
    try {
        await scwin.excelDown()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf31207.btn_ExcelDown_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description btn_window 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = async function(e){
    try {
        await $c.win.print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31207.btn_window_onclick' }); }
};scwin.frame = undefined;

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_makeExcelData
 * @description make Excel Data 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_makeExcelData = async function () {
    try { return await $c.data.downFile("/bizspt/excelDown.jsp", "", ($c.util.getComponent("dma_makeExcelDataReq") ? $c.util.getComponent("dma_makeExcelDataReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
