/**
 * @method
 * @name calc
 * @description calc 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calc = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : $c.util.getComponent('ipt_ISU_CD').focus());
        return;
    }
    if (($c.util.getComponent('cal_basicDate').getValue() == null ? '' : String($c.util.getComponent('cal_basicDate').getValue())) === '') {
        await $c.win.alert("[기준일]을 입력하세요.");
        $c.util.getComponent("cal_basicDate").focus();
        return;
    }
    const basicVal = $c.date.isDate($c.util.getComponent('cal_basicDate').getValue());
    if (basicVal === false) {
        await $c.win.alert("[기준일]의 날짜형식이 정확하지 않습니다.");
        $c.util.getComponent("cal_basicDate").focus();
        return;
    }
    if (($c.util.getComponent('slc_sameCategory').getValue() == null ? '' : String($c.util.getComponent('slc_sameCategory').getValue())) === '') {
        await $c.win.alert("동일업종을 선택하세요.");
        $c.util.getComponent("slc_sameCategory").focus();
        return;
    }
    const directStartVal = $c.date.isDate($c.util.getComponent('cal_directStartDate').getValue());
    if (directStartVal === false) {
        await $c.win.alert("[직접입력 시작일]의 날짜형식이 정확하지 않습니다.");
        $c.util.getComponent("cal_directStartDate").focus();
        return;
    }
    const directEndVal = $c.date.isDate($c.util.getComponent('cal_directEndDate').getValue());
    if (directEndVal === false) {
        await $c.win.alert("[직접입력 종료일]의 날짜형식이 정확하지 않습니다.");
        $c.util.getComponent("cal_directEndDate").focus();
        return;
    }
    if (($c.util.getComponent('cal_directStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_directStartDate').getValue())) === '' && ($c.util.getComponent('cal_directEndDate').getValue() == null ? '' : String($c.util.getComponent('cal_directEndDate').getValue())) !== '') {
        await $c.win.alert("[직접입력] 시작일을 선택하세요.");
        $c.util.getComponent("cal_directStartDate").focus();
        return;
    }
    if (($c.util.getComponent('cal_directEndDate').getValue() == null ? '' : String($c.util.getComponent('cal_directEndDate').getValue())) === '' && ($c.util.getComponent('cal_directStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_directStartDate').getValue())) !== '') {
        await $c.win.alert("[직접입력] 종료일을 선택하세요.");
        $c.util.getComponent("cal_directEndDate").focus();
        return;
    }
    if ($c.util.getComponent('cal_directStartDate').getValue()> $c.util.getComponent('cal_directEndDate').getValue()) {
        await $c.win.alert("[직접입력] 시작일을 종료일 이전으로 선택하세요.");
        $c.util.getComponent("cal_directStartDate").focus();
        return;
    }
    $c.util.getComponent("dma_makeExcelDataReq").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_makeExcelDataReq").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    $c.util.getComponent('dma_makeExcelDataReq').set('method', "calculateStockChangeRate");
    const result = await scwin.tx_fn_Calc_xhr();
    const xmlDoc = xmlDocLoad(result);
    const dom = xmlDoc.selectNodes("//DATASET//DATA");
    $c.util.getComponent("ipt_day3StartDate").setValue(dom.item(0).selectSingleNode('DAY3_START_DATE').text);
    $c.util.getComponent("ipt_day3EndDate").setValue(dom.item(0).selectSingleNode('DAY3_END_DATE').text);
    $c.util.getComponent("ipt_weekStartDate").setValue(dom.item(0).selectSingleNode('WEEK_START_DATE').text);
    $c.util.getComponent("ipt_weekEndDate").setValue(dom.item(0).selectSingleNode('WEEK_END_DATE').text);
    $c.util.getComponent("ipt_day15StartDate").setValue(dom.item(0).selectSingleNode('DAY15_START_DATE').text);
    $c.util.getComponent("ipt_day15EndDate").setValue(dom.item(0).selectSingleNode('DAY15_END_DATE').text);
    $c.util.getComponent("ipt_monthStartDate").setValue(dom.item(0).selectSingleNode('MONTH_START_DATE').text);
    $c.util.getComponent("ipt_monthEndDate").setValue(dom.item(0).selectSingleNode('MONTH_END_DATE').text);
    $c.util.getComponent("cal_directStartDate").setValue(dom.item(0).selectSingleNode('DIRECT_START_DATE').text);
    $c.util.getComponent("cal_directEndDate").setValue(dom.item(0).selectSingleNode('DIRECT_END_DATE').text);
    $c.util.getComponent("ipt_day3StockChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DAY3_STOCK_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_weekStockChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('WEEK_STOCK_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_day15StockChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DAY15_STOCK_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_monthStockChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('MONTH_STOCK_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_directStockChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DIRECT_STOCK_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_day3IndexChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DAY3_INDEX_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_weekIndexChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('WEEK_INDEX_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_day15IndexChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DAY15_INDEX_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_monthIndexChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('MONTH_INDEX_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_directIndexChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DIRECT_INDEX_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_day3IndexChangeRateExcess").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DAY3_INDEX_CHANGE_RATE_EXCESS').text)));
    $c.util.getComponent("ipt_weekIndexChangeRateExcess").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('WEEK_INDEX_CHANGE_RATE_EXCESS').text)));
    $c.util.getComponent("ipt_day15IndexChangeRateExcess").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DAY15_INDEX_CHANGE_RATE_EXCESS').text)));
    $c.util.getComponent("ipt_monthIndexChangeRateExcess").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('MONTH_INDEX_CHANGE_RATE_EXCESS').text)));
    $c.util.getComponent("ipt_directIndexChangeRateExcess").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DIRECT_INDEX_CHANGE_RATE_EXCESS').text)));
    $c.util.getComponent("ipt_day3TrdvolAvg").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DAY3_TRDVOL_AVG').text)));
    $c.util.getComponent("ipt_weekTrdvolAvg").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('WEEK_TRDVOL_AVG').text)));
    $c.util.getComponent("ipt_day15TrdvolAvg").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DAY15_TRDVOL_AVG').text)));
    $c.util.getComponent("ipt_monthTrdvolAvg").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('MONTH_TRDVOL_AVG').text)));
    $c.util.getComponent("ipt_directTrdvolAvg").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DIRECT_TRDVOL_AVG').text)));
    $c.util.getComponent("ipt_yearDay3TrdvolAvg").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('YEAR_TRDVOL_AVG').text)));
    $c.util.getComponent("ipt_yearWeekTrdvolAvg").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('YEAR_TRDVOL_AVG').text)));
    $c.util.getComponent("ipt_yearDay15TrdvolAvg").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('YEAR_TRDVOL_AVG').text)));
    $c.util.getComponent("ipt_yearMonthTrdvolAvg").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('YEAR_TRDVOL_AVG').text)));
    if (($c.util.getComponent('cal_directStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_directStartDate').getValue())) === '') {
        $c.util.getComponent("ipt_yearDirectTrdvolAvg").setValue("0");
    } else {
        $c.util.getComponent("ipt_yearDirectTrdvolAvg").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('YEAR_TRDVOL_AVG').text)));
    }
    $c.util.getComponent("ipt_day3TrdvolChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DAY3_TRDVOL_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_weekTrdvolChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('WEEK_TRDVOL_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_day15TrdvolChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DAY15_TRDVOL_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_monthTrdvolChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('MONTH_TRDVOL_CHANGE_RATE').text)));
    $c.util.getComponent("ipt_directTrdvolChangeRate").setValue(scwin.setComma(scwin.isNull(dom.item(0).selectSingleNode('DIRECT_TRDVOL_CHANGE_RATE').text)));
};

/**
 * @method
 * @name setComma
 * @description set Comma 처리
 * @param {*} numstr numstr
 * @returns {void}
 * @hidden N
 */
scwin.setComma = function (numstr) {
    numstr = String(numstr);
    const re0 = /^(-?\d+)(\d{3})($|\..*$)/;
    if (re0.test(numstr)) {
        return numstr.replace(re0, function(str, p1, p2, p3) {
                return scwin.setComma(p1) + ',' + p2 + p3;
        });
    } else {
        return numstr;
    }
};

/**
 * @method
 * @name checkNum
 * @description check Num 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkNum = function () {
    if (event.keyCode === 8 || event.keyCode === 46) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 37 && $c.util.getKeyCode(event) <= 40) {
        return;
    }
    if ($c.util.getKeyCode(event) >= 48 && $c.util.getKeyCode(event) <= 57) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 96 && $c.util.getKeyCode(event) <= 105) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function () {
    if (($c.util.getComponent('ipt_monthStartDate').getValue() == null ? '' : String($c.util.getComponent('ipt_monthStartDate').getValue())) === '') {
        await $c.win.alert("[계산하기]을 실행 후 다운로드 할 수 있습니다.");
        return;
    }
    $c.util.getComponent("dma_makeExcelDataReq").set("ISU_CD", $c.util.getComponent('ipt_ISU_CD').getValue());
    $c.util.getComponent("dma_makeExcelDataReq").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    $c.util.getComponent('dma_makeExcelDataReq').set('method', "excelCalculateStockChangeRate");
    const result = await scwin.tx_fn_ExcelDown_xhr();
    await scwin.makeExcelData(result);
};

/**
 * @method
 * @name makeExcelData
 * @description make Excel Data 처리
 * @param {*} xml xml
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.makeExcelData = async function (xml) {
    const xmlDoc = xmlDocLoad(xml);
    const dom = xmlDoc.selectNodes("//DATASET//DATA");
    let excelData = "";
    excelData += "<table class='table_board_default_3' width='880' border='1' id='id_excelData' style='display:none'";
    excelData += "<tr>";
    excelData += "<td class='board_subject_3' width='150' align='center'>대표종목</td>";
    excelData += "<td class='board_subject_3' width='180' align='center'>동일업종</td>";
    excelData += "<td class='board_subject_3' width='150' align='center'>거래일</td>";
    excelData += "<td class='board_subject_3' width='200' align='center'>종목주가</td>";
    excelData += "<td class='board_subject_3' width='200' align='center'>지수주가</td>";
    excelData += "<td class='board_subject_3' width='200' align='center'>거래량</td>";
    excelData += "</tr>";
    for (scwin.i = 0; scwin.i < dom.length; scwin.i++) {
        excelData += "<tr>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('com_nm').text + "</td>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('idx_ind_nm').text + "</td>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('trd_dd').text + "</td>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('stockprice').text + "</td>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('indexprice').text + "</td>";
        excelData += "<td class='board_title_2'>" + dom.item(scwin.i).selectSingleNode('acc_trdvol').text + "</td>";
        excelData += "</tr>";
    }
    excelData += "</table>";
    self.id_excelData.outerHTML = excelData;
    $c.util.getComponent('dma_makeExcelDataReq').set('excelData', self.id_excelData.outerHTML);
    scwin.form_frmISU_CD.method = "post";
    scwin.form_frmISU_CD.target = "_blank";
    scwin.form_frmISU_CD.action = "/bizspt/excelDown.jsp";
    await scwin.tx_makeExcelData();
};

