/**
 * @method
 * @name makeCategory
 * @description make Category 처리
 * @param {*} xml xml
 * @returns {void}
 * @hidden N
 */
scwin.makeCategory = function (xml) {
    const xmlDoc = xmlDocLoad(xml);
    const dom = xmlDoc.selectNodes("//DATASET//DATA");
    const obj = $c.util.getComponent('slc_sameCategory');
    const objLength = obj.length;
    for (scwin.i = 0; scwin.i < dom.length; scwin.i++) {
        const text = dom.item(scwin.i).selectSingleNode('idx_ind_nm').text;
        const value = dom.item(scwin.i).selectSingleNode('idx_id').text;
        obj[scwin.i+1] = new Option(text, value);
    }
};

/**
 * @method
 * @name isNull
 * @description is Null 처리
 * @param {*} value value
 * @returns {void}
 * @hidden N
 */
scwin.isNull = function (value) {
    if (value === 'null' || value === '') {
        value = '0';
    }
    return value;
};
